// src/components/MainSection.js
import React, { useState } from "react";
import axios from "axios"; // Add axios import for API requests

const MainSection = () => {
  // State for active tab (user or vendor)
  const [activeTab, setActiveTab] = useState("user");

  // User form state
  const [userFormData, setUserFormData] = useState({
    name: "",
    phone: "",
    marketingConsent: true,
    interests: [],
  });

  // Vendor form state
  const [vendorFormData, setVendorFormData] = useState({
    businessName: "",
    contactName: "",
    phone: "",
    businessType: "",
    description: "",
    termsAgreed: false,
  });

  // Shared states for form handling
  const [formSubmitted, setFormSubmitted] = useState(false);
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  // Handle user form input changes
  const handleUserChange = (e) => {
    const { name, value } = e.target;
    setUserFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  // Handle vendor form input changes
  const handleVendorChange = (e) => {
    const { name, value, type, checked } = e.target;
    setVendorFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Handle checkbox changes for user form
  const handleUserCheckboxChange = (e) => {
    const { name, value, checked } = e.target;

    // Handle marketing consent checkbox
    if (name === "marketingConsent") {
      setUserFormData((prev) => ({
        ...prev,
        marketingConsent: checked,
      }));
      return;
    }

    // Handle interests checkboxes
    setUserFormData((prev) => {
      if (checked) {
        return { ...prev, interests: [...prev.interests, value] };
      } else {
        return {
          ...prev,
          interests: prev.interests.filter((interest) => interest !== value),
        };
      }
    });
  };

  // Reset form state when switching tabs
  const handleTabChange = (tab) => {
    setActiveTab(tab);
    setFormSubmitted(false);
    setError("");
  };

  // Submit user registration form
  const handleUserSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    // Basic validation
    if (!userFormData.name || !userFormData.phone) {
      setError("Name and phone number are required");
      setLoading(false);
      return;
    }

    // Validate phone number format
    const phoneRegex = /^\+?[0-9]{10,15}$/;
    if (!phoneRegex.test(userFormData.phone)) {
      setError("Please enter a valid phone number (10-15 digits)");
      setLoading(false);
      return;
    }

    try {
      // Use the correct API endpoint from your backend
      const apiUrl = process.env.REACT_APP_API_URL || "http://localhost:3001";
      const response = await axios.post(
        `${apiUrl}/api/users/register`,
        userFormData
      );

      if (response.status === 201) {
        setFormSubmitted(true);
        setUserFormData({
          name: "",
          phone: "",
          marketingConsent: true,
          interests: [],
        });
      } else {
        setError(
          response.data.message || "Registration failed. Please try again."
        );
      }
    } catch (error) {
      console.error("Error submitting form:", error);
      if (error.response) {
        setError(
          error.response.data.message ||
            "Registration failed. Please try again."
        );
      } else if (error.request) {
        setError(
          "No response from server. Please check your connection and try again."
        );
      } else {
        setError("Connection error. Please try again later.");
      }
    } finally {
      setLoading(false);
    }
  };

  // Submit vendor registration form
  const handleVendorSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setLoading(true);

    // Basic validation
    if (
      !vendorFormData.businessName ||
      !vendorFormData.contactName ||
      !vendorFormData.phone ||
      !vendorFormData.businessType
    ) {
      setError("All required fields must be filled out");
      setLoading(false);
      return;
    }

    // Validate phone number format
    const phoneRegex = /^\+?[0-9]{10,15}$/;
    if (!phoneRegex.test(vendorFormData.phone)) {
      setError("Please enter a valid phone number (10-15 digits)");
      setLoading(false);
      return;
    }

    // Validate terms agreement
    if (!vendorFormData.termsAgreed) {
      setError("You must agree to the Terms of Service");
      setLoading(false);
      return;
    }

    try {
      // Create data to send to API - omit termsAgreed as it's not needed in backend
      const vendorData = {
        businessName: vendorFormData.businessName,
        contactName: vendorFormData.contactName,
        phone: vendorFormData.phone,
        businessType: vendorFormData.businessType,
        description: vendorFormData.description,
      };

      // Use the correct API endpoint from your backend
      const apiUrl = process.env.REACT_APP_API_URL || "http://localhost:3001";
      const response = await axios.post(
        `${apiUrl}/api/vendors/register`,
        vendorData
      );

      if (response.status === 201) {
        setFormSubmitted(true);
        setVendorFormData({
          businessName: "",
          contactName: "",
          phone: "",
          businessType: "",
          description: "",
          termsAgreed: false,
        });
      } else {
        setError(
          response.data.message || "Registration failed. Please try again."
        );
      }
    } catch (error) {
      console.error("Error submitting form:", error);
      if (error.response) {
        setError(
          error.response.data.message ||
            "Registration failed. Please try again."
        );
      } else if (error.request) {
        setError(
          "No response from server. Please check your connection and try again."
        );
      } else {
        setError("Connection error. Please try again later.");
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <section id="main" className="py-16 px-4 bg-snap-light">
      <div className="container mx-auto">
        <h2 className="text-3xl font-bold mb-6 text-center text-snap-dark">
          Join the iibsy Platform
        </h2>
        <p className="text-lg mb-8 text-center text-snap-gray max-w-3xl mx-auto">
          Join our growing community and be part of the future of tech shopping.
          Register today to receive updates and early access.
        </p>

        {/* Tabs */}
        <div className="flex justify-center mb-10">
          <div className="inline-flex rounded-md shadow-sm" role="group">
            <button
              type="button"
              className={`px-6 py-3 text-sm font-medium rounded-l-lg ${
                activeTab === "user"
                  ? "bg-snap-red text-white"
                  : "bg-white text-snap-dark hover:bg-gray-100"
              }`}
              onClick={() => handleTabChange("user")}
            >
              I'm a User
            </button>
            <button
              type="button"
              className={`px-6 py-3 text-sm font-medium rounded-r-lg ${
                activeTab === "vendor"
                  ? "bg-snap-red text-white"
                  : "bg-white text-snap-dark hover:bg-gray-100"
              }`}
              onClick={() => handleTabChange("vendor")}
            >
              I'm a Vendor
            </button>
          </div>
        </div>

        {/* User Registration Form */}
        {activeTab === "user" && (
          <div className="max-w-md mx-auto bg-white p-6 rounded-lg shadow-md">
            <h3 className="text-xl font-semibold mb-4 text-snap-dark">
              User Registration
            </h3>
            {formSubmitted ? (
              <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded">
                <p className="font-medium mb-1">Thank you for registering!</p>
                <p>
                  We'll notify you when the iibsy Platform launches. Watch for
                  updates on your WhatsApp number.
                </p>
              </div>
            ) : (
              <form onSubmit={handleUserSubmit}>
                {error && (
                  <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                    <p>{error}</p>
                  </div>
                )}

                <div className="mb-4">
                  <label htmlFor="name" className="block text-snap-gray mb-2">
                    Full Name <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={userFormData.name}
                    onChange={handleUserChange}
                    required
                    placeholder="Enter your full name"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                </div>

                <div className="mb-4">
                  <label htmlFor="phone" className="block text-snap-gray mb-2">
                    WhatsApp / Phone Number{" "}
                    <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={userFormData.phone}
                    onChange={handleUserChange}
                    required
                    placeholder="+1 123 456 7890"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                  <p className="text-xs text-snap-gray mt-1">
                    We'll notify you about our launch via WhatsApp
                  </p>
                </div>

                <div className="mb-4">
                  <p className="block text-snap-gray mb-2">
                    I'm interested in (select all that apply):
                  </p>
                  <div className="grid grid-cols-2 gap-2">
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="smartphones"
                        checked={userFormData.interests.includes("smartphones")}
                        onChange={handleUserCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Smartphones</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="laptops"
                        checked={userFormData.interests.includes("laptops")}
                        onChange={handleUserCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Laptops</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="audio"
                        checked={userFormData.interests.includes("audio")}
                        onChange={handleUserCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Audio Devices</span>
                    </label>
                    <label className="flex items-center">
                      <input
                        type="checkbox"
                        name="interests"
                        value="gaming"
                        checked={userFormData.interests.includes("gaming")}
                        onChange={handleUserCheckboxChange}
                        className="mr-2"
                      />
                      <span className="text-snap-gray">Gaming</span>
                    </label>
                  </div>
                </div>

                <div className="mb-6">
                  <label className="flex items-start cursor-pointer">
                    <input
                      type="checkbox"
                      name="marketingConsent"
                      checked={userFormData.marketingConsent}
                      onChange={handleUserCheckboxChange}
                      className="mt-1 mr-2"
                    />
                    <span className="text-sm text-snap-gray">
                      I agree to receive updates, promotions, and offers from
                      iibsy Platform via WhatsApp or SMS.
                    </span>
                  </label>
                </div>

                <button
                  type="submit"
                  className="w-full bg-snap-red hover:bg-snap-dark text-snap-light font-bold py-3 px-4 rounded-md transition duration-300 flex justify-center items-center"
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <svg
                        className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
                        xmlns="http://www.w3.org/2000/svg"
                        fill="none"
                        viewBox="0 0 24 24"
                      >
                        <circle
                          className="opacity-25"
                          cx="12"
                          cy="12"
                          r="10"
                          stroke="currentColor"
                          strokeWidth="4"
                        ></circle>
                        <path
                          className="opacity-75"
                          fill="currentColor"
                          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                        ></path>
                      </svg>
                      Processing...
                    </>
                  ) : (
                    "Join the Waitlist"
                  )}
                </button>
              </form>
            )}
          </div>
        )}

        {/* Vendor Registration Form */}
        {activeTab === "vendor" && (
          <div className="max-w-md mx-auto bg-white p-6 rounded-lg shadow-md">
            <h3 className="text-xl font-semibold mb-4 text-snap-dark">
              Vendor Registration
            </h3>
            {formSubmitted ? (
              <div className="bg-green-100 border border-green-400 text-green-700 px-4 py-3 rounded">
                <p className="font-medium mb-1">
                  Thank you for registering your business!
                </p>
                <p>
                  We'll be in touch with more information about joining the
                  iibsy Platform as a vendor. Watch for a message on your
                  provided WhatsApp number.
                </p>
              </div>
            ) : (
              <form onSubmit={handleVendorSubmit}>
                {error && (
                  <div className="bg-red-100 border border-red-400 text-red-700 px-4 py-3 rounded mb-4">
                    <p>{error}</p>
                  </div>
                )}

                <div className="mb-4">
                  <label
                    htmlFor="businessName"
                    className="block text-snap-gray mb-2"
                  >
                    Business Name <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="text"
                    id="businessName"
                    name="businessName"
                    value={vendorFormData.businessName}
                    onChange={handleVendorChange}
                    required
                    placeholder="Your business name"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                </div>

                <div className="mb-4">
                  <label
                    htmlFor="contactName"
                    className="block text-snap-gray mb-2"
                  >
                    Contact Person <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="text"
                    id="contactName"
                    name="contactName"
                    value={vendorFormData.contactName}
                    onChange={handleVendorChange}
                    required
                    placeholder="Your full name"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                </div>

                <div className="mb-4">
                  <label htmlFor="phone" className="block text-snap-gray mb-2">
                    WhatsApp / Phone Number{" "}
                    <span className="text-snap-red">*</span>
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={vendorFormData.phone}
                    onChange={handleVendorChange}
                    required
                    placeholder="+1 123 456 7890"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  />
                  <p className="text-xs text-snap-gray mt-1">
                    We'll use this for order notifications and customer
                    inquiries
                  </p>
                </div>

                <div className="mb-4">
                  <label
                    htmlFor="businessType"
                    className="block text-snap-gray mb-2"
                  >
                    Business Type <span className="text-snap-red">*</span>
                  </label>
                  <select
                    id="businessType"
                    name="businessType"
                    value={vendorFormData.businessType}
                    onChange={handleVendorChange}
                    required
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  >
                    <option value="">Select a business type</option>
                    <option value="electronics">Electronics/Tech Store</option>
                    <option value="computers">Computer/Laptop Shop</option>
                    <option value="mobile">Mobile/Smartphone Store</option>
                    <option value="audio">Audio/Headphones</option>
                    <option value="accessories">Tech Accessories</option>
                    <option value="repairs">Repair Services</option>
                    <option value="other">Other</option>
                  </select>
                </div>

                <div className="mb-4">
                  <label
                    htmlFor="description"
                    className="block text-snap-gray mb-2"
                  >
                    Business Description
                  </label>
                  <textarea
                    id="description"
                    name="description"
                    value={vendorFormData.description}
                    onChange={handleVendorChange}
                    rows="3"
                    placeholder="Tell us about your business and products"
                    className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-snap-red"
                  ></textarea>
                </div>

                <div className="mb-6">
                  <label className="flex items-start cursor-pointer">
                    <input
                      type="checkbox"
                      name="termsAgreed"
                      checked={vendorFormData.termsAgreed}
                      onChange={handleVendorChange}
                      required
                      className="mt-1 mr-2"
                    />
                    <span className="text-sm text-snap-gray">
                      I agree to the iibsy Platform's{" "}
                      <a href="/terms-of-service" className="text-snap-red">
                        Terms of Service
                      </a>
                    </span>
                  </label>
                </div>

                <button
                  type="submit"
                  className="w-full bg-snap-red hover:bg-snap-dark text-snap-light font-bold py-3 px-4 rounded-md transition duration-300 flex justify-center items-center"
                  disabled={loading}
                >
                  {loading ? (
                    <>
                      <svg
                        className="animate-spin -ml-1 mr-3 h-5 w-5 text-white"
                        xmlns="http://www.w3.org/2000/svg"
                        fill="none"
                        viewBox="0 0 24 24"
                      >
                        <circle
                          className="opacity-25"
                          cx="12"
                          cy="12"
                          r="10"
                          stroke="currentColor"
                          strokeWidth="4"
                        ></circle>
                        <path
                          className="opacity-75"
                          fill="currentColor"
                          d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
                        ></path>
                      </svg>
                      Processing...
                    </>
                  ) : (
                    "Submit Application"
                  )}
                </button>
              </form>
            )}
          </div>
        )}

        {/* Features section that's visible regardless of tab */}
        <div className="mt-16">
          <h3 className="text-2xl font-bold text-center mb-8 text-snap-dark">
            Platform Features
          </h3>
          <div className="grid md:grid-cols-3 gap-6">
            <div className="bg-white p-6 rounded-lg shadow-md">
              <div className="w-12 h-12 bg-snap-red bg-opacity-10 flex items-center justify-center rounded-lg mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M12 18h.01M8 21h8a2 2 0 002-2V5a2 2 0 00-2-2H8a2 2 0 00-2 2v14a2 2 0 002 2z"
                  />
                </svg>
              </div>
              <h4 className="text-lg font-semibold mb-2 text-snap-dark">
                Mobile First
              </h4>
              <p className="text-snap-gray">
                Our platform is optimized for mobile devices, making shopping
                and selling on-the-go simple and convenient.
              </p>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-md">
              <div className="w-12 h-12 bg-snap-red bg-opacity-10 flex items-center justify-center rounded-lg mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M17 8h2a2 2 0 012 2v6a2 2 0 01-2 2h-2v4l-4-4H9a1.994 1.994 0 01-1.414-.586m0 0L11 14h4a2 2 0 002-2V6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2v4l.586-.586z"
                  />
                </svg>
              </div>
              <h4 className="text-lg font-semibold mb-2 text-snap-dark">
                Direct Communication
              </h4>
              <p className="text-snap-gray">
                Connect directly with vendors or customers through our
                integrated WhatsApp messaging system.
              </p>
            </div>

            <div className="bg-white p-6 rounded-lg shadow-md">
              <div className="w-12 h-12 bg-snap-red bg-opacity-10 flex items-center justify-center rounded-lg mb-4">
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="h-6 w-6 text-snap-red"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z"
                  />
                </svg>
              </div>
              <h4 className="text-lg font-semibold mb-2 text-snap-dark">
                Secure Transactions
              </h4>
              <p className="text-snap-gray">
                Every transaction is protected by our secure payment system with
                easy tracking and monitoring.
              </p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default MainSection;
